fn create_row(v: &Vec<f32>, i: usize) -> Vec<f32> {
    let n = v.len();
    (0..n)
        .map(|j| if j == i { v[i] } else { 0.0 })
        .collect()
}

fn diagflat(v: Vec<f32>) -> Vec<Vec<f32>> {
    let n = v.len();
    (0..n)
        .map(|i| create_row(&v, i))
        .collect()
}

// Example usage and test
fn main() {
    let v = vec![1.0, 2.5, -3.2];
    let m = diagflat(v);
    // m should be:
    // [
    //   [ 1.0,  0.0,  0.0],
    //   [ 0.0,  2.5,  0.0],
    //   [ 0.0,  0.0, -3.2],
    // ]
    for row in m {
        println!("{:?}", row);
    }
}